/**
 * 潜次事件类型。
 */
public final class EventTypes {

    /** 观察期出现症状，启动加压舱预案 */
    public static final String CHAMBER_PROTOCOL = "CHAMBER_PROTOCOL";
    /** 结案后迟到的体征数据，只记迟到事件 */
    public static final String LATE_VITALS = "LATE_VITALS";
    /** 减压方案变更，旧方案与其记录被冻结 */
    public static final String PLAN_FROZEN = "PLAN_FROZEN";

    private EventTypes() {
    }
}

package com.example.starter.support;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;

/**
 * 业务时间一律使用 UTC；H2 DATETIME 列不带时区，统一在边界换算。
 */
public final class Times {

    private Times() {
    }

    public static LocalDateTime toSql(Instant instant) {
        return LocalDateTime.ofInstant(instant, ZoneOffset.UTC);
    }

    public static Instant fromSql(LocalDateTime value) {
        return value == null ? null : value.toInstant(ZoneOffset.UTC);
    }
}

package com.example.starter.support;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.Map;
import java.util.TreeMap;

/**
 * 幂等指纹：覆盖 requestId 与全部业务字段，字段按名字典序规范化后做 SHA-256。
 */
public final class Fingerprints {

    private static final ObjectMapper CANONICAL = new ObjectMapper()
            .configure(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS, true);

    private Fingerprints() {
    }

    public static String sha256(Map<String, Object> fields) {
        try {
            TreeMap<String, Object> sorted = new TreeMap<>(fields);
            byte[] body = CANONICAL.writeValueAsBytes(sorted);
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(body));
        } catch (JsonProcessingException | NoSuchAlgorithmException e) {
            throw new IllegalStateException("指纹计算失败", e);
        }
    }

    public static String sha256Utf8(String text) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(text.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("指纹计算失败", e);
        }
    }
}

package com.example.starter.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Clock;

/**
 * 统一时钟（UTC）；测试可替换为固定时钟，业务时刻优先采用请求自带的作业时间。
 */
@Configuration
public class TimeConfig {

    @Bean
    public Clock systemClock() {
        return Clock.systemUTC();
    }
}

