package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;

/**
 * 作业申请请求。
 *
 * @param requestId       申请/潜次业务键，同时是幂等键
 * @param diverACode      组员一工号
 * @param diverBCode      组员二工号
 * @param plannedDepthM   计划深度，米
 * @param plannedBottomMin 计划水下时间，分钟
 */
public record ApplyRequest(
        @NotBlank String requestId,
        @NotBlank String diverACode,
        @NotBlank String diverBCode,
        @Positive int plannedDepthM,
        @Positive int plannedBottomMin) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;

/**
 * 减压方案生成/变更请求；requestId 为本次操作的幂等键。
 *
 * @param requestId 操作幂等键
 * @param depthM    方案深度，米
 * @param bottomMin 方案底时间，分钟（不得超过该深度免减压极限，恰在极限合法）
 */
public record PlanRequest(
        @NotBlank String requestId,
        @Positive int depthM,
        @Positive int bottomMin) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.time.Instant;

/**
 * 水下记录提交请求（单人一条，两人同阶段成对后生效）。
 *
 * @param requestId   操作幂等键
 * @param diverCode   提交潜水员工号，必须是本潜次组员
 * @param phase       DESCENT/BOTTOM/ASCENT
 * @param fromDepthM  起始深度，米
 * @param toDepthM    目标深度，米
 * @param durationMin 该段历时，分钟（正整数）
 * @param eventTime   该段作业时刻（UTC），用于速率、台账与 24 小时窗口复算
 */
public record RecordRequest(
        @NotBlank String requestId,
        @NotBlank String diverCode,
        @NotBlank String phase,
        @PositiveOrZero int fromDepthM,
        @PositiveOrZero int toDepthM,
        @PositiveOrZero int durationMin,
        @NotNull Instant eventTime) {

    /** 校验注解无法表达的跨字段规则。 */
    public void validate() {
        if (durationMin <= 0) {
            throw new IllegalArgumentException("durationMin 必须为正数");
        }
    }
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

import java.time.Instant;

/**
 * 出水登记请求，出水后进入 2 小时观察期。
 *
 * @param requestId  操作幂等键
 * @param surfacedAt 出水时刻（UTC）；为空取服务时钟
 */
public record SurfaceRequest(
        @NotBlank String requestId,
        Instant surfacedAt) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 观察期体征上报。
 *
 * @param requestId  操作幂等键
 * @param symptomatic 是否出现症状：TRUE 立即启动加压舱预案并冻结结案
 * @param observedAt 体征观测时刻（UTC），为空取服务时钟
 */
public record VitalsRequest(
        @NotBlank String requestId,
        @NotNull Boolean symptomatic,
        Instant observedAt) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

import java.time.Instant;

/**
 * 结案请求；出水后观察须恰满 2 小时且无症状。
 *
 * @param requestId 操作幂等键
 * @param closedAt  结案时刻（UTC），为空取服务时钟
 */
public record CloseRequest(
        @NotBlank String requestId,
        Instant closedAt) {
}

