    @Test
    void sameDiverTwice_rejected() throws Exception {
        mockMvc.perform(post("/api/dives/apply").contentType("application/json")
                        .content(Requests.apply(objectMapper, "DIVE-SAME", "D001", "D001", 18, 50)))
                .andExpect(status().isBadRequest());
    }

    /** 构造一个已成对执行完 BOTTOM（状态 DIVING）的潜次，供出水/观察类用例复用。 */
    private void prepareDivingDive(String id, String a, String b, int depth, int bottom,
                                   Instant base) throws Exception {
        post("/api/dives/apply", Requests.apply(objectMapper, id, a, b, depth, bottom));
        post("/api/dives/plans", Requests.plan(objectMapper, "PLAN-" + id, id, depth, bottom));
        int transit = (int) Math.ceil(depth / 18.0);
        post("/api/dives/records", Requests.record(objectMapper, "RD-" + id + "-1", id, a,
                "DESCENT", 0, depth, transit, base));
        post("/api/dives/records", Requests.record(objectMapper, "RD-" + id + "-2", id, b,
                "DESCENT", 0, depth, transit, base));
        post("/api/dives/records", Requests.record(objectMapper, "RB-" + id + "-1", id, a,
                "BOTTOM", depth, depth, bottom, base.plusSeconds(60L * transit)));
        post("/api/dives/records", Requests.record(objectMapper, "RB-" + id + "-2", id, b,
                "BOTTOM", depth, depth, bottom, base.plusSeconds(60L * transit)));
        post("/api/dives/records", Requests.record(objectMapper, "RA-" + id + "-1", id, a,
                "ASCENT", depth, 0, transit, base.plusSeconds(60L * (transit + bottom))));
        post("/api/dives/records", Requests.record(objectMapper, "RA-" + id + "-2", id, b,
                "ASCENT", depth, 0, transit, base.plusSeconds(60L * (transit + bottom))));
    }
}

